@Test
public void getWhenUsingObservationRegistryThenObservesRequest() {
    UsernamePasswordMetadata credentials = new UsernamePasswordMetadata("rob", "password");
    // @formatter:off
    this.requester = RSocketRequester.builder().setupMetadata(credentials, MimeTypeUtils.parseMimeType(WellKnownMimeType.MESSAGE_RSOCKET_AUTHENTICATION.getString())).rsocketStrategies(this.handler.getRSocketStrategies()).connectTcp("localhost", this.server.address().getPort()).block();
    // @formatter:on
    String data = "rob";
    // @formatter:off
    this.requester.route("secure.retrieve-mono").metadata(credentials, MimeTypeUtils.parseMimeType(WellKnownMimeType.MESSAGE_RSOCKET_AUTHENTICATION.getString())).data(data).retrieveMono(String.class).block();
    // @formatter:on
    ArgumentCaptor<Observation.Context> captor = ArgumentCaptor.forClass(Observation.Context.class);
    verify(this.observationHandler, times(2)).onStart(captor.capture());
    Iterator<Observation.Context> contexts = captor.getAllValues().iterator();
    // once for setup
    assertThat(contexts.next().getName()).isEqualTo("spring.security.authentications");
    // once for request
    assertThat(contexts.next().getName()).isEqualTo("spring.security.authentications");
}

@Bean
RSocketMessageHandler messageHandler() {
    RSocketMessageHandler handler = new RSocketMessageHandler();
    handler.setRSocketStrategies(rsocketStrategies());
    return handler;
}

@Bean
ObservationRegistry observationRegistry() {
    given(this.handler.supportsContext(any())).willReturn(true);
    ObservationRegistry registry = ObservationRegistry.create();
    registry.observationConfig().observationHandler(this.handler);
    return registry;
