@Test
public void getWhenDefaultFilterChainBeanThenDefaultHeadersInResponse() throws Exception {
    this.spring.register(DefaultWithFilterChainConfig.class).autowire();
    // @formatter:off
    MvcResult mvcResult = this.mockMvc.perform(get("/").secure(true)).andExpect(header().string(HttpHeaders.X_CONTENT_TYPE_OPTIONS, "nosniff")).andExpect(header().string(HttpHeaders.X_FRAME_OPTIONS, XFrameOptionsHeaderWriter.XFrameOptionsMode.DENY.name())).andExpect(header().string(HttpHeaders.STRICT_TRANSPORT_SECURITY, "max-age=31536000 ; includeSubDomains")).andExpect(header().string(HttpHeaders.CACHE_CONTROL, "no-cache, no-store, max-age=0, must-revalidate")).andExpect(header().string(HttpHeaders.EXPIRES, "0")).andExpect(header().string(HttpHeaders.PRAGMA, "no-cache")).andExpect(header().string(HttpHeaders.X_XSS_PROTECTION, "0")).andReturn();
    // @formatter:on
    assertThat(mvcResult.getResponse().getHeaderNames()).containsExactlyInAnyOrder(HttpHeaders.X_CONTENT_TYPE_OPTIONS, HttpHeaders.X_FRAME_OPTIONS, HttpHeaders.STRICT_TRANSPORT_SECURITY, HttpHeaders.CACHE_CONTROL, HttpHeaders.EXPIRES, HttpHeaders.PRAGMA, HttpHeaders.X_XSS_PROTECTION);
}

