    OAuth2TokenExchangeActor actor2 = new OAuth2TokenExchangeActor(Map.of(JwtClaimNames.ISS, ISSUER_2, JwtClaimNames.SUB, "actor2"));
    OAuth2TokenExchangeCompositeAuthenticationToken principal = new OAuth2TokenExchangeCompositeAuthenticationToken(subject, List.of(actor1, actor2));
    // @formatter:off
    JwtEncodingContext tokenContext = JwtEncodingContext.with(this.jwsHeaderBuilder, this.jwtClaimsBuilder).tokenType(OAuth2TokenType.ACCESS_TOKEN).principal(principal).authorizationGrant(tokenExchangeAuthentication).build();
    // @formatter:on
    DefaultOAuth2TokenCustomizers.jwtCustomizer().customize(tokenContext);
    JwtClaimsSet jwtClaimsSet = this.jwtClaimsBuilder.build();
    assertThat(jwtClaimsSet.getClaims()).isNotEmpty();
    assertThat(jwtClaimsSet.getClaims()).hasSize(2);
    assertThat(jwtClaimsSet.getClaims().get("act")).isNotNull();
    @SuppressWarnings("unchecked")
    Map<String, Object> actClaim1 = (Map<String, Object>) jwtClaimsSet.getClaims().get("act");
    assertThat(actClaim1.get(JwtClaimNames.ISS)).isEqualTo(ISSUER_1);
    assertThat(actClaim1.get(JwtClaimNames.SUB)).isEqualTo("actor1");
