    Map<String, Object> actClaim2 = (Map<String, Object>) actClaim1.get("act");
    assertThat(actClaim2.get(JwtClaimNames.ISS)).isEqualTo(ISSUER_2);
    assertThat(actClaim2.get(JwtClaimNames.SUB)).isEqualTo("actor2");
}

