@Test
public void requestWhenAuthorizationEndpointCustomizedThenUsed() throws Exception {
    this.spring.register(AuthorizationServerConfigurationCustomAuthorizationEndpoint.class).autowire();
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().build();
    TestingAuthenticationToken principal = new TestingAuthenticationToken("principalName", "password");
    OAuth2AuthorizationCode authorizationCode = new OAuth2AuthorizationCode("code", Instant.now(), Instant.now().plus(5, ChronoUnit.MINUTES));
    OAuth2AuthorizationCodeRequestAuthenticationToken authorizationCodeRequestAuthenticationResult = new OAuth2AuthorizationCodeRequestAuthenticationToken("https://provider.com/oauth2/authorize", registeredClient.getClientId(), principal, authorizationCode, registeredClient.getRedirectUris().iterator().next(), STATE_URL_UNENCODED, registeredClient.getScopes());
    given(authorizationRequestConverter.convert(any())).willReturn(authorizationCodeRequestAuthenticationResult);
    given(authorizationRequestAuthenticationProvider.supports(eq(OAuth2AuthorizationCodeRequestAuthenticationToken.class))).willReturn(true);
    given(authorizationRequestAuthenticationProvider.authenticate(any())).willReturn(authorizationCodeRequestAuthenticationResult);
    this.mvc.perform(get(DEFAULT_AUTHORIZATION_ENDPOINT_URI).params(getAuthorizationRequestParameters(registeredClient)).with(user("user"))).andExpect(status().isOk());
    verify(authorizationRequestConverter).convert(any());
    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<AuthenticationConverter>> authenticationConvertersCaptor = ArgumentCaptor.forClass(List.class);
    verify(authorizationRequestConvertersConsumer).accept(authenticationConvertersCaptor.capture());
    List<AuthenticationConverter> authenticationConverters = authenticationConvertersCaptor.getValue();
    assertThat(authenticationConverters).allMatch((converter) -> converter == authorizationRequestConverter || converter instanceof OAuth2AuthorizationCodeRequestAuthenticationConverter || converter instanceof OAuth2AuthorizationConsentAuthenticationConverter);
    verify(authorizationRequestAuthenticationProvider).authenticate(eq(authorizationCodeRequestAuthenticationResult));
    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<AuthenticationProvider>> authenticationProvidersCaptor = ArgumentCaptor.forClass(List.class);
    verify(authorizationRequestAuthenticationProvidersConsumer).accept(authenticationProvidersCaptor.capture());
    List<AuthenticationProvider> authenticationProviders = authenticationProvidersCaptor.getValue();
    assertThat(authenticationProviders).allMatch((provider) -> provider == authorizationRequestAuthenticationProvider || provider instanceof OAuth2AuthorizationCodeRequestAuthenticationProvider || provider instanceof OAuth2AuthorizationConsentAuthenticationProvider);
    verify(authorizationResponseHandler).onAuthenticationSuccess(any(), any(), eq(authorizationCodeRequestAuthenticationResult));
}

