    http.authorizeHttpRequests((authorize) -> authorize.anyRequest().authenticated()).oauth2ResourceServer((oauth2) -> oauth2.jwt(withDefaults()).withObjectPostProcessor(new ObjectPostProcessor<BearerTokenAuthenticationFilter>() {

