private void testRefreshTokenGrant() {
    OAuth2AccessTokenResponse accessTokenResponse = TestOAuth2AccessTokenResponses.accessTokenResponse().build();
    given(MOCK_RESPONSE_CLIENT.getTokenResponse(any(OAuth2RefreshTokenGrantRequest.class))).willReturn(Mono.just(accessTokenResponse));
    TestingAuthenticationToken authentication = new TestingAuthenticationToken("user", null, "ROLE_USER");
    ClientRegistration clientRegistration = this.clientRegistrationRepository.findByRegistrationId("google").block();
    assertThat(clientRegistration).isNotNull();
    OAuth2AuthorizedClient existingAuthorizedClient = new OAuth2AuthorizedClient(clientRegistration, authentication.getName(), getExpiredAccessToken(), TestOAuth2RefreshTokens.refreshToken());
    this.authorizedClientRepository.saveAuthorizedClient(existingAuthorizedClient, authentication, this.exchange).block();
    // @formatter:off
    OAuth2AuthorizeRequest authorizeRequest = OAuth2AuthorizeRequest.withClientRegistrationId(clientRegistration.getRegistrationId()).principal(authentication).attribute(ServerWebExchange.class.getName(), this.exchange).build();
    // @formatter:on
    OAuth2AuthorizedClient authorizedClient = this.authorizedClientManager.authorize(authorizeRequest).block();
    assertThat(authorizedClient).isNotNull();
    ArgumentCaptor<OAuth2RefreshTokenGrantRequest> grantRequestCaptor = ArgumentCaptor.forClass(OAuth2RefreshTokenGrantRequest.class);
    verify(MOCK_RESPONSE_CLIENT).getTokenResponse(grantRequestCaptor.capture());
    OAuth2RefreshTokenGrantRequest grantRequest = grantRequestCaptor.getValue();
    assertThat(grantRequest.getClientRegistration().getRegistrationId()).isEqualTo(clientRegistration.getRegistrationId());
    assertThat(grantRequest.getGrantType()).isEqualTo(AuthorizationGrantType.REFRESH_TOKEN);
    assertThat(grantRequest.getAccessToken()).isEqualTo(existingAuthorizedClient.getAccessToken());
    assertThat(grantRequest.getRefreshToken()).isEqualTo(existingAuthorizedClient.getRefreshToken());
}

