@Test
void validateWhenSameRequestMatchersArePresentThenUnreachableFilterChainException() {
    PathPatternRequestMatcher.Builder builder = PathPatternRequestMatcher.withDefaults();
    AnonymousAuthenticationFilter authenticationFilter = mock(AnonymousAuthenticationFilter.class);
    ExceptionTranslationFilter exceptionTranslationFilter = mock(ExceptionTranslationFilter.class);
    SecurityFilterChain chain1 = new DefaultSecurityFilterChain(builder.matcher("/api"), authenticationFilter, exceptionTranslationFilter, this.authorizationInterceptor);
    SecurityFilterChain chain2 = new DefaultSecurityFilterChain(builder.matcher("/api"), authenticationFilter, exceptionTranslationFilter, this.authorizationInterceptor);
    List<SecurityFilterChain> chains = new ArrayList<>();
    chains.add(chain2);
    chains.add(chain1);
    FilterChainProxy proxy = new FilterChainProxy(chains);
    assertThatExceptionOfType(UnreachableFilterChainException.class).isThrownBy(() -> this.validator.validate(proxy));
}

