@Test
@SuppressWarnings("unchecked")
public void oauth2ClientWhenCustomAccessTokenResponseClientThenUsed() {
    this.spring.register(OAuth2ClientBeanConfig.class, AuthorizedClientController.class).autowire();
    ReactiveClientRegistrationRepository clientRegistrationRepository = this.spring.getContext().getBean(ReactiveClientRegistrationRepository.class);
    given(clientRegistrationRepository.findByRegistrationId(any())).willReturn(Mono.just(this.registration));
    ServerOAuth2AuthorizedClientRepository authorizedClientRepository = this.spring.getContext().getBean(ServerOAuth2AuthorizedClientRepository.class);
    given(authorizedClientRepository.saveAuthorizedClient(any(OAuth2AuthorizedClient.class), any(Authentication.class), any(ServerWebExchange.class))).willReturn(Mono.empty());
    ServerAuthorizationRequestRepository<OAuth2AuthorizationRequest> authorizationRequestRepository = this.spring.getContext().getBean(ServerAuthorizationRequestRepository.class);
    OAuth2AuthorizationRequest authorizationRequest = TestOAuth2AuthorizationRequests.request().redirectUri("/authorize/oauth2/code/registration-id").build();
    given(authorizationRequestRepository.loadAuthorizationRequest(any(ServerWebExchange.class))).willReturn(Mono.just(authorizationRequest));
    given(authorizationRequestRepository.removeAuthorizationRequest(any(ServerWebExchange.class))).willReturn(Mono.just(authorizationRequest));
    ReactiveOAuth2AccessTokenResponseClient<OAuth2AuthorizationCodeGrantRequest> accessTokenResponseClient = this.spring.getContext().getBean(ReactiveOAuth2AccessTokenResponseClient.class);
    OAuth2AccessTokenResponse accessTokenResponse = OAuth2AccessTokenResponse.withToken("token").tokenType(OAuth2AccessToken.TokenType.BEARER).scopes(Set.of()).expiresIn(300).build();
    given(accessTokenResponseClient.getTokenResponse(any(OAuth2AuthorizationCodeGrantRequest.class))).willReturn(Mono.just(accessTokenResponse));
    // @formatter:off
    this.client.get().uri((uriBuilder) -> uriBuilder.path("/authorize/oauth2/code/registration-id").queryParam(OAuth2ParameterNames.CODE, "code").queryParam(OAuth2ParameterNames.STATE, "state").build()).exchange().expectStatus().is3xxRedirection();
    // @formatter:on
    ArgumentCaptor<OAuth2AuthorizationCodeGrantRequest> grantRequestArgumentCaptor = ArgumentCaptor.forClass(OAuth2AuthorizationCodeGrantRequest.class);
    verify(accessTokenResponseClient).getTokenResponse(grantRequestArgumentCaptor.capture());
    OAuth2AuthorizationCodeGrantRequest grantRequest = grantRequestArgumentCaptor.getValue();
    assertThat(grantRequest.getClientRegistration()).isEqualTo(this.registration);
    assertThat(grantRequest.getGrantType()).isEqualTo(AuthorizationGrantType.AUTHORIZATION_CODE);
    assertThat(grantRequest.getAuthorizationExchange().getAuthorizationRequest()).isEqualTo(authorizationRequest);
    assertThat(grantRequest.getAuthorizationExchange().getAuthorizationResponse().getCode()).isEqualTo("code");
    assertThat(grantRequest.getAuthorizationExchange().getAuthorizationResponse().getState()).isEqualTo("state");
    assertThat(grantRequest.getAuthorizationExchange().getAuthorizationResponse().getRedirectUri()).startsWith("/authorize/oauth2/code/registration-id");
}

