@Test
public void csrfServerLogoutHandlerAppliedIfCsrfIsEnabled() {
    SecurityWebFilterChain securityWebFilterChain = this.http.csrf((csrf) -> csrf.csrfTokenRepository(this.csrfTokenRepository)).build();
    assertThat(getWebFilter(securityWebFilterChain, CsrfWebFilter.class)).get().extracting((csrfWebFilter) -> ReflectionTestUtils.getField(csrfWebFilter, "csrfTokenRepository")).isEqualTo(this.csrfTokenRepository);
    Optional<ServerLogoutHandler> logoutHandler = getWebFilter(securityWebFilterChain, LogoutWebFilter.class).map((logoutWebFilter) -> (ServerLogoutHandler) ReflectionTestUtils.getField(logoutWebFilter, LogoutWebFilter.class, "logoutHandler"));
    assertThat(logoutHandler).get().isExactlyInstanceOf(DelegatingServerLogoutHandler.class).extracting((delegatingLogoutHandler) -> ((List<ServerLogoutHandler>) ReflectionTestUtils.getField(delegatingLogoutHandler, DelegatingServerLogoutHandler.class, "delegates")).stream().map(ServerLogoutHandler::getClass).collect(Collectors.toList())).isEqualTo(Arrays.asList(SecurityContextServerLogoutHandler.class, CsrfServerLogoutHandler.class));
}

@Test
public void postWhenCustomRequestHandlerThenUsed() {
    CsrfToken csrfToken = new DefaultCsrfToken("headerName", "paramName", "tokenValue");
    given(this.csrfTokenRepository.loadToken(any(ServerWebExchange.class))).willReturn(Mono.just(csrfToken));
    given(this.csrfTokenRepository.generateToken(any(ServerWebExchange.class))).willReturn(Mono.empty());
    ServerCsrfTokenRequestHandler requestHandler = mock(ServerCsrfTokenRequestHandler.class);
    given(requestHandler.resolveCsrfTokenValue(any(ServerWebExchange.class), any(CsrfToken.class))).willReturn(Mono.just(csrfToken.getToken()));
    // @formatter:off
    this.http.csrf((csrf) -> csrf.csrfTokenRepository(this.csrfTokenRepository).csrfTokenRequestHandler(requestHandler));
    // @formatter:on
    WebTestClient client = buildClient();
    client.post().uri("/").exchange().expectStatus().isOk();
    verify(this.csrfTokenRepository, times(2)).loadToken(any(ServerWebExchange.class));
    verify(this.csrfTokenRepository).generateToken(any(ServerWebExchange.class));
    verify(requestHandler).handle(any(ServerWebExchange.class), any());
    verify(requestHandler).resolveCsrfTokenValue(any(ServerWebExchange.class), any());
}

