private void prepareOAuth2Config() {
    OAuth2LoginConcurrentSessionsConfig config = this.spring.getContext().getBean(OAuth2LoginConcurrentSessionsConfig.class);
    ServerAuthenticationConverter converter = config.authenticationConverter;
    ReactiveAuthenticationManager manager = config.manager;
    ServerOAuth2AuthorizationRequestResolver resolver = config.resolver;
    OAuth2AuthorizationExchange exchange = TestOAuth2AuthorizationExchanges.success();
    OAuth2User user = TestOAuth2Users.create();
    OAuth2AccessToken accessToken = TestOAuth2AccessTokens.noScopes();
    OAuth2LoginAuthenticationToken result = new OAuth2LoginAuthenticationToken(TestClientRegistrations.clientRegistration().build(), exchange, user, user.getAuthorities(), accessToken);
    given(converter.convert(any())).willReturn(Mono.just(new TestingAuthenticationToken("a", "b", "c")));
    given(manager.authenticate(any())).willReturn(Mono.just(result));
    given(resolver.resolve(any())).willReturn(Mono.empty());
}

