@Bean
SecurityWebFilterChain springSecurityFilter(ServerHttpSecurity http, DefaultWebSessionManager webSessionManager) {
    // @formatter:off
    http.authorizeExchange((authorize) -> authorize.anyExchange().authenticated()).oauth2Login((oauth2Login) -> oauth2Login.authenticationConverter(this.authenticationConverter).authenticationManager(this.manager).authorizationRequestResolver(this.resolver)).sessionManagement((sessionManagement) -> sessionManagement.concurrentSessions((concurrentSessions) -> concurrentSessions.maximumSessions(SessionLimit.of(maxSessions)).maximumSessionsExceededHandler(preventLogin ? new PreventLoginServerMaximumSessionsExceededHandler() : new InvalidateLeastUsedServerMaximumSessionsExceededHandler(webSessionManager.getSessionStore()))));
    // @formatter:on
    return http.build();
}

