@Test
void checkWhenMessageTypeAndPathPatternMatches() {
    Mockito.when(this.provider.getIfUnique(any())).thenReturn(PathPatternMessageMatcher.withDefaults());
    AuthorizationManager<Message<?>> authorizationManager = builder().simpMessageDestMatchers("/destination").permitAll().simpSubscribeDestMatchers("/destination").denyAll().anyMessage().denyAll().build();
    MessageHeaders headers = new MessageHeaders(Map.of(SimpMessageHeaderAccessor.MESSAGE_TYPE_HEADER, SimpMessageType.MESSAGE, SimpMessageHeaderAccessor.DESTINATION_HEADER, "/destination"));
    Message<?> message = new GenericMessage<>(new Object(), headers);
    assertThat(authorizationManager.authorize(mock(Supplier.class), message).isGranted()).isTrue();
    MessageHeaders headers2 = new MessageHeaders(Map.of(SimpMessageHeaderAccessor.MESSAGE_TYPE_HEADER, SimpMessageType.SUBSCRIBE, SimpMessageHeaderAccessor.DESTINATION_HEADER, "/destination"));
    Message<?> message2 = new GenericMessage<>(new Object(), headers2);
    assertThat(authorizationManager.authorize(mock(Supplier.class), message2).isGranted()).isFalse();
}

@Test
void checkWhenMessageTypeAndPathPatternMatchesCaseInsensitive() {
    PathPatternParser pathPatternParser = new PathPatternParser();
    pathPatternParser.setCaseSensitive(false);
    PathPatternMessageMatcher.Builder messageMatcherBuilder = PathPatternMessageMatcher.withPathPatternParser(pathPatternParser);
