@Test
public void authenticateWhenInvalidClaimsThenThrowOAuth2AuthenticationException() {
    // @formatter:off
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().clientSecret(TestKeys.DEFAULT_ENCODED_SECRET_KEY).clientAuthenticationMethod(ClientAuthenticationMethod.CLIENT_SECRET_JWT).clientSettings(ClientSettings.builder().tokenEndpointAuthenticationSigningAlgorithm(MacAlgorithm.HS256).build()).build();
    // @formatter:on
    given(this.registeredClientRepository.findByClientId(eq(registeredClient.getClientId()))).willReturn(registeredClient);
    // @formatter:off
    JwsHeader jwsHeader = JwsHeader.with(MacAlgorithm.HS256).build();
    JwtClaimsSet jwtClaimsSet = JwtClaimsSet.builder().issuer("invalid-iss").subject("invalid-sub").audience(Collections.singletonList("invalid-aud")).build();
    // @formatter:on
    JwtEncoder jwsEncoder = createEncoder(TestKeys.DEFAULT_ENCODED_SECRET_KEY, "HmacSHA256");
    Jwt jwtAssertion = jwsEncoder.encode(JwtEncoderParameters.from(jwsHeader, jwtClaimsSet));
    OAuth2ClientAuthenticationToken authentication = new OAuth2ClientAuthenticationToken(registeredClient.getClientId(), JWT_CLIENT_ASSERTION_AUTHENTICATION_METHOD, jwtAssertion.getTokenValue(), null);
    assertThatExceptionOfType(OAuth2AuthenticationException.class).isThrownBy(() -> this.authenticationProvider.authenticate(authentication)).withCauseInstanceOf(JwtValidationException.class).satisfies((ex) -> {
        assertThat(ex.getError().getErrorCode()).isEqualTo(OAuth2ErrorCodes.INVALID_CLIENT);
        assertThat(ex.getError().getDescription()).contains(OAuth2ParameterNames.CLIENT_ASSERTION);
        JwtValidationException jwtValidationException = (JwtValidationException) ex.getCause();
        // iss, sub,
        assertThat(jwtValidationException.getErrors()).hasSize(4);
        // aud, exp
    });
}

