    OAuth2AuthorizationCodeAuthenticationToken authentication = new OAuth2AuthorizationCodeAuthenticationToken(AUTHORIZATION_CODE, clientPrincipal, authorizationRequest.getRedirectUri(), null);
    given(this.jwtEncoder.encode(any())).willReturn(createJwt());
    willAnswer((answer) -> {
        OAuth2TokenContext context = answer.getArgument(0);
        if (OAuth2TokenType.REFRESH_TOKEN.equals(context.getTokenType())) {
            return new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "access-token", Instant.now(), Instant.now().plusSeconds(300));
        } else {
            return answer.callRealMethod();
        }
    }).given(this.tokenGenerator).generate(any());
    assertThatExceptionOfType(OAuth2AuthenticationException.class).isThrownBy(() -> this.authenticationProvider.authenticate(authentication)).extracting(OAuth2AuthenticationException::getError).satisfies((error) -> {
        assertThat(error.getErrorCode()).isEqualTo(OAuth2ErrorCodes.SERVER_ERROR);
        assertThat(error.getDescription()).contains("The token generator failed to generate a valid refresh token.");
    });
}

