public void authenticateWhenRequireAuthorizationConsentThenReturnAuthorizationConsent() {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().clientSettings(ClientSettings.builder().requireAuthorizationConsent(true).build()).build();
    given(this.registeredClientRepository.findByClientId(eq(registeredClient.getClientId()))).willReturn(registeredClient);
