@Test
public void authenticateWhenValidAccessTokenThenReturnClientRegistration() {
    Jwt jwt = createJwtClientRegistration();
    OAuth2AccessToken jwtAccessToken = new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, jwt.getTokenValue(), jwt.getIssuedAt(), jwt.getExpiresAt(), jwt.getClaim(OAuth2ParameterNames.SCOPE));
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().build();
    OAuth2Authorization authorization = TestOAuth2Authorizations.authorization(registeredClient, jwtAccessToken, jwt.getClaims()).build();
    given(this.authorizationService.findByToken(eq(jwtAccessToken.getTokenValue()), eq(OAuth2TokenType.ACCESS_TOKEN))).willReturn(authorization);
    JwtAuthenticationToken principal = new JwtAuthenticationToken(jwt, AuthorityUtils.createAuthorityList("SCOPE_client.create"));
    // @formatter:off
    OAuth2ClientRegistration clientRegistration = OAuth2ClientRegistration.builder().clientName("client-name").redirectUri("https://client.example.com").grantType(AuthorizationGrantType.AUTHORIZATION_CODE.getValue()).grantType(AuthorizationGrantType.CLIENT_CREDENTIALS.getValue()).scope("scope1").scope("scope2").build();
    // @formatter:on
    OAuth2ClientRegistrationAuthenticationToken authentication = new OAuth2ClientRegistrationAuthenticationToken(principal, clientRegistration);
    OAuth2ClientRegistrationAuthenticationToken authenticationResult = (OAuth2ClientRegistrationAuthenticationToken) this.authenticationProvider.authenticate(authentication);
    ArgumentCaptor<RegisteredClient> registeredClientCaptor = ArgumentCaptor.forClass(RegisteredClient.class);
    ArgumentCaptor<OAuth2Authorization> authorizationCaptor = ArgumentCaptor.forClass(OAuth2Authorization.class);
    verify(this.authorizationService).findByToken(eq(jwtAccessToken.getTokenValue()), eq(OAuth2TokenType.ACCESS_TOKEN));
    verify(this.registeredClientRepository).save(registeredClientCaptor.capture());
    verify(this.authorizationService).save(authorizationCaptor.capture());
    verify(this.passwordEncoder).encode(any());
    // assert "initial" access token is invalidated
    OAuth2Authorization authorizationResult = authorizationCaptor.getValue();
    assertThat(authorizationResult.getAccessToken().isInvalidated()).isTrue();
    if (authorizationResult.getRefreshToken() != null) {
        assertThat(authorizationResult.getRefreshToken().isInvalidated()).isTrue();
    }
    assertClientRegistration(clientRegistration, authenticationResult.getClientRegistration(), registeredClientCaptor.getValue());
}

