public void authenticateWhenValidRefreshTokenThenReturnIdToken() {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().scope(OidcScopes.OPENID).build();
    OidcIdToken authorizedIdToken = OidcIdToken.withTokenValue("id-token").issuer("https://provider.com").subject("subject").issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(60)).claim("sid", "sessionId-1234").claim(IdTokenClaimNames.AUTH_TIME, Date.from(Instant.now())).build();
