    OAuth2TokenExchangeAuthenticationToken authentication = new OAuth2TokenExchangeAuthenticationToken(JWT_TOKEN_TYPE_VALUE, SUBJECT_TOKEN, ACCESS_TOKEN_TYPE_VALUE, clientPrincipal, null, null, RESOURCES, AUDIENCES, registeredClient.getScopes(), additionalParameters);
    TestingAuthenticationToken userPrincipal = new TestingAuthenticationToken("user", null, "ROLE_USER");
    // @formatter:off
    OAuth2Authorization subjectAuthorization = TestOAuth2Authorizations.authorization(registeredClient).token(createAccessToken(SUBJECT_TOKEN)).attribute(Principal.class.getName(), userPrincipal).build();
    // @formatter:on
    given(this.authorizationService.findByToken(anyString(), any(OAuth2TokenType.class))).willReturn(subjectAuthorization);
    OAuth2AccessToken accessToken = createAccessToken("token-value");
    given(this.tokenGenerator.generate(any(OAuth2TokenContext.class))).willReturn(accessToken);
    OAuth2AccessTokenAuthenticationToken authenticationResult = (OAuth2AccessTokenAuthenticationToken) this.authenticationProvider.authenticate(authentication);
    assertThat(authenticationResult.getRegisteredClient()).isEqualTo(registeredClient);
    assertThat(authenticationResult.getPrincipal()).isEqualTo(authentication.getPrincipal());
    assertThat(authenticationResult.getAccessToken()).isEqualTo(accessToken);
    assertThat(authenticationResult.getRefreshToken()).isNull();
    assertThat(authenticationResult.getAdditionalParameters()).hasSize(1);
    assertThat(authenticationResult.getAdditionalParameters().get(OAuth2ParameterNames.ISSUED_TOKEN_TYPE)).isEqualTo(JWT_TOKEN_TYPE_VALUE);
    ArgumentCaptor<OAuth2Authorization> authorizationCaptor = ArgumentCaptor.forClass(OAuth2Authorization.class);
    ArgumentCaptor<OAuth2TokenContext> tokenContextCaptor = ArgumentCaptor.forClass(OAuth2TokenContext.class);
