    RegisteredClient registeredClient = TestRegisteredClients.registeredPublicClient().build();
    given(this.registeredClientRepository.findByClientId(eq(registeredClient.getClientId()))).willReturn(registeredClient);
    OAuth2Authorization authorization = TestOAuth2Authorizations.authorization(registeredClient, createPkceAuthorizationParametersS256()).build();
    given(this.authorizationService.findByToken(eq(AUTHORIZATION_CODE), eq(AUTHORIZATION_CODE_TOKEN_TYPE))).willReturn(authorization);
    Map<String, Object> parameters = createPkceTokenParameters(S256_CODE_VERIFIER);
    parameters.put(OAuth2ParameterNames.CODE, "invalid-code");
    OAuth2ClientAuthenticationToken authentication = new OAuth2ClientAuthenticationToken(registeredClient.getClientId(), ClientAuthenticationMethod.NONE, null, parameters);
