@Test
public void authenticateWhenValidAccessTokenThenReturnClientRegistration() {
    Jwt jwt = createJwtClientConfiguration();
    OAuth2AccessToken jwtAccessToken = new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, jwt.getTokenValue(), jwt.getIssuedAt(), jwt.getExpiresAt(), jwt.getClaim(OAuth2ParameterNames.SCOPE));
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().clientAuthenticationMethods((clientAuthenticationMethods) -> {
        clientAuthenticationMethods.clear();
        clientAuthenticationMethods.add(ClientAuthenticationMethod.PRIVATE_KEY_JWT);
    }).clientSettings(ClientSettings.builder().tokenEndpointAuthenticationSigningAlgorithm(SignatureAlgorithm.RS512).jwkSetUrl("https://client.example.com/jwks").build()).build();
    OAuth2Authorization authorization = TestOAuth2Authorizations.authorization(registeredClient, jwtAccessToken, jwt.getClaims()).build();
    given(this.authorizationService.findByToken(eq(jwtAccessToken.getTokenValue()), eq(OAuth2TokenType.ACCESS_TOKEN))).willReturn(authorization);
    given(this.registeredClientRepository.findByClientId(eq(registeredClient.getClientId()))).willReturn(registeredClient);
    JwtAuthenticationToken principal = new JwtAuthenticationToken(jwt, AuthorityUtils.createAuthorityList("SCOPE_client.read"));
    OidcClientRegistrationAuthenticationToken authentication = new OidcClientRegistrationAuthenticationToken(principal, registeredClient.getClientId());
    OidcClientRegistrationAuthenticationToken authenticationResult = (OidcClientRegistrationAuthenticationToken) this.authenticationProvider.authenticate(authentication);
    verify(this.authorizationService).findByToken(eq(jwtAccessToken.getTokenValue()), eq(OAuth2TokenType.ACCESS_TOKEN));
    verify(this.registeredClientRepository).findByClientId(eq(registeredClient.getClientId()));
    // verify that the "registration" access token is not invalidated after it is used
    verify(this.authorizationService, never()).save(eq(authorization));
    assertThat(authorization.getAccessToken().isInvalidated()).isFalse();
    OidcClientRegistration clientRegistrationResult = authenticationResult.getClientRegistration();
    assertThat(clientRegistrationResult.getClientId()).isEqualTo(registeredClient.getClientId());
    assertThat(clientRegistrationResult.getClientIdIssuedAt()).isEqualTo(registeredClient.getClientIdIssuedAt());
    assertThat(clientRegistrationResult.getClientSecret()).isEqualTo(registeredClient.getClientSecret());
    assertThat(clientRegistrationResult.getClientSecretExpiresAt()).isEqualTo(registeredClient.getClientSecretExpiresAt());
    assertThat(clientRegistrationResult.getClientName()).isEqualTo(registeredClient.getClientName());
    assertThat(clientRegistrationResult.getRedirectUris()).containsExactlyInAnyOrderElementsOf(registeredClient.getRedirectUris());
    List<String> grantTypes = new ArrayList<>();
    registeredClient.getAuthorizationGrantTypes().forEach((authorizationGrantType) -> grantTypes.add(authorizationGrantType.getValue()));
    assertThat(clientRegistrationResult.getGrantTypes()).containsExactlyInAnyOrderElementsOf(grantTypes);
    assertThat(clientRegistrationResult.getResponseTypes()).containsExactly(OAuth2AuthorizationResponseType.CODE.getValue());
    assertThat(clientRegistrationResult.getScopes()).containsExactlyInAnyOrderElementsOf(registeredClient.getScopes());
    assertThat(clientRegistrationResult.getTokenEndpointAuthenticationMethod()).isEqualTo(registeredClient.getClientAuthenticationMethods().iterator().next().getValue());
    assertThat(clientRegistrationResult.getTokenEndpointAuthenticationSigningAlgorithm()).isEqualTo(registeredClient.getClientSettings().getTokenEndpointAuthenticationSigningAlgorithm().getName());
    assertThat(clientRegistrationResult.getJwkSetUrl().toString()).isEqualTo(registeredClient.getClientSettings().getJwkSetUrl());
    assertThat(clientRegistrationResult.getIdTokenSignedResponseAlgorithm()).isEqualTo(registeredClient.getTokenSettings().getIdTokenSignatureAlgorithm().getName());
    AuthorizationServerContext authorizationServerContext = AuthorizationServerContextHolder.getContext();
    String expectedRegistrationClientUrl = UriComponentsBuilder.fromUriString(authorizationServerContext.getIssuer()).path(authorizationServerContext.getAuthorizationServerSettings().getOidcClientRegistrationEndpoint()).queryParam(OAuth2ParameterNames.CLIENT_ID, registeredClient.getClientId()).toUriString();
    assertThat(clientRegistrationResult.getRegistrationClientUrl().toString()).isEqualTo(expectedRegistrationClientUrl);
    assertThat(clientRegistrationResult.getRegistrationAccessToken()).isNull();
}

