private void authenticateValidIdToken(Authentication principal, RegisteredClient registeredClient, String sessionId, OidcIdToken idToken) {
    OAuth2Authorization authorization = TestOAuth2Authorizations.authorization(registeredClient).principalName(principal.getName()).token(idToken, (metadata) -> metadata.put(OAuth2Authorization.Token.CLAIMS_METADATA_NAME, idToken.getClaims())).build();
    given(this.authorizationService.findByToken(eq(idToken.getTokenValue()), eq(ID_TOKEN_TOKEN_TYPE))).willReturn(authorization);
