    assertThat(clientRegistrationResponse.getTokenEndpointAuthenticationMethod()).isEqualTo(expectedClientRegistrationResponse.getTokenEndpointAuthenticationMethod());
    assertThat(clientRegistrationResponse.getIdTokenSignedResponseAlgorithm()).isEqualTo(expectedClientRegistrationResponse.getIdTokenSignedResponseAlgorithm());
    assertThat(clientRegistrationResponse.getRegistrationAccessToken()).isEqualTo(expectedClientRegistrationResponse.getRegistrationAccessToken());
