    String userInfoEndpoint = "/userinfo";
    String logoutEndpoint = "/connect/logout";
    String tokenRevocationEndpoint = "/oauth2/v1/revoke";
    String tokenIntrospectionEndpoint = "/oauth2/v1/introspect";
    AuthorizationServerSettings authorizationServerSettings = AuthorizationServerSettings.builder().issuer(issuer).authorizationEndpoint(authorizationEndpoint).pushedAuthorizationRequestEndpoint(pushedAuthorizationRequestEndpoint).tokenEndpoint(tokenEndpoint).jwkSetEndpoint(jwkSetEndpoint).oidcUserInfoEndpoint(userInfoEndpoint).oidcLogoutEndpoint(logoutEndpoint).tokenRevocationEndpoint(tokenRevocationEndpoint).tokenIntrospectionEndpoint(tokenIntrospectionEndpoint).build();
