public void doFilterWhenAuthorizationRequestAuthenticationExceptionThenErrorResponse() throws Exception {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().redirectUris((redirectUris) -> {
        redirectUris.clear();
        redirectUris.add("https://example.com?param=encoded%20parameter%20value");
    }).build();
    OAuth2AuthorizationCodeRequestAuthenticationToken authorizationCodeRequestAuthentication = new OAuth2AuthorizationCodeRequestAuthenticationToken(AUTHORIZATION_URI, registeredClient.getClientId(), this.principal, registeredClient.getRedirectUris().iterator().next(), "client state", registeredClient.getScopes(), null);
    OAuth2Error error = new OAuth2Error(OAuth2ErrorCodes.INVALID_REQUEST, "error description", "error uri");
    given(this.authenticationManager.authenticate(any())).willThrow(new OAuth2AuthorizationCodeRequestAuthenticationException(error, authorizationCodeRequestAuthentication));
    MockHttpServletRequest request = createAuthorizationRequest(registeredClient);
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    verify(this.authenticationManager).authenticate(any());
    verifyNoInteractions(filterChain);
    assertThat(response.getStatus()).isEqualTo(HttpStatus.FOUND.value());
    assertThat(response.getRedirectedUrl()).isEqualTo("https://example.com?param=encoded%20parameter%20value&error=invalid_request&error_description=error%20description&error_uri=error%20uri&state=client%20state");
    assertThat(SecurityContextHolder.getContext().getAuthentication()).isSameAs(this.principal);
}

