    given(this.authenticationConverter.convert(any(HttpServletRequest.class))).willReturn(new OAuth2ClientAuthenticationToken(registeredClient.getClientId(), ClientAuthenticationMethod.CLIENT_SECRET_BASIC, registeredClient.getClientSecret(), null));
