    ArgumentCaptor<OAuth2ClientAuthenticationToken> authenticationRequestCaptor = ArgumentCaptor.forClass(OAuth2ClientAuthenticationToken.class);
    verify(this.authenticationManager).authenticate(authenticationRequestCaptor.capture());
    assertThat(authenticationRequestCaptor).extracting(ArgumentCaptor::getValue).extracting(OAuth2ClientAuthenticationToken::getDetails).asInstanceOf(InstanceOfAssertFactories.type(WebAuthenticationDetails.class)).extracting(WebAuthenticationDetails::getRemoteAddress).isEqualTo(remoteAddress);
}

