@Test
public void doFilterWhenTokenIntrospectionRequestValidThenSuccessResponse() throws Exception {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().build();
    Authentication clientPrincipal = new OAuth2ClientAuthenticationToken(registeredClient, ClientAuthenticationMethod.CLIENT_SECRET_BASIC, registeredClient.getClientSecret());
    OAuth2AccessToken accessToken = new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "token", Instant.now(), Instant.now().plus(Duration.ofHours(1)), new HashSet<>(Arrays.asList("scope1", "scope2")));
    // @formatter:off
    OAuth2TokenIntrospection tokenClaims = OAuth2TokenIntrospection.builder(true).clientId("authorized-client-id").username("authorizing-username").issuedAt(accessToken.getIssuedAt()).expiresAt(accessToken.getExpiresAt()).scopes((scopes) -> scopes.addAll(accessToken.getScopes())).tokenType(accessToken.getTokenType().getValue()).notBefore(accessToken.getIssuedAt()).subject("authorizing-subject").audience("authorized-client-id").issuer("https://provider.com").id("jti").build();
    // @formatter:on
    OAuth2TokenIntrospectionAuthenticationToken tokenIntrospectionAuthenticationResult = new OAuth2TokenIntrospectionAuthenticationToken(accessToken.getTokenValue(), clientPrincipal, tokenClaims);
    given(this.authenticationManager.authenticate(any())).willReturn(tokenIntrospectionAuthenticationResult);
    SecurityContext securityContext = SecurityContextHolder.createEmptyContext();
    securityContext.setAuthentication(clientPrincipal);
    SecurityContextHolder.setContext(securityContext);
    MockHttpServletRequest request = createTokenIntrospectionRequest(accessToken.getTokenValue(), OAuth2TokenType.ACCESS_TOKEN.getValue());
    request.addParameter("custom-param-1", "custom-value-1");
    request.addParameter("custom-param-2", "custom-value-1", "custom-value-2");
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    ArgumentCaptor<OAuth2TokenIntrospectionAuthenticationToken> tokenIntrospectionAuthentication = ArgumentCaptor.forClass(OAuth2TokenIntrospectionAuthenticationToken.class);
    verifyNoInteractions(filterChain);
    verify(this.authenticationManager).authenticate(tokenIntrospectionAuthentication.capture());
    assertThat(response.getStatus()).isEqualTo(HttpStatus.OK.value());
    assertThat(tokenIntrospectionAuthentication.getValue().getAdditionalParameters()).contains(entry("custom-param-1", "custom-value-1"), entry("custom-param-2", new String[] { "custom-value-1", "custom-value-2" }));
    OAuth2TokenIntrospection tokenIntrospectionResponse = readTokenIntrospectionResponse(response);
    assertThat(tokenIntrospectionResponse.isActive()).isEqualTo(tokenClaims.isActive());
    assertThat(tokenIntrospectionResponse.getClientId()).isEqualTo(tokenClaims.getClientId());
    assertThat(tokenIntrospectionResponse.getUsername()).isEqualTo(tokenClaims.getUsername());
    assertThat(tokenIntrospectionResponse.getIssuedAt()).isBetween(tokenClaims.getIssuedAt().minusSeconds(1), tokenClaims.getIssuedAt().plusSeconds(1));
    assertThat(tokenIntrospectionResponse.getExpiresAt()).isBetween(tokenClaims.getExpiresAt().minusSeconds(1), tokenClaims.getExpiresAt().plusSeconds(1));
    assertThat(tokenIntrospectionResponse.getScopes()).containsExactlyInAnyOrderElementsOf(tokenClaims.getScopes());
    assertThat(tokenIntrospectionResponse.getTokenType()).isEqualTo(tokenClaims.getTokenType());
    assertThat(tokenIntrospectionResponse.getNotBefore()).isBetween(tokenClaims.getNotBefore().minusSeconds(1), tokenClaims.getNotBefore().plusSeconds(1));
    assertThat(tokenIntrospectionResponse.getSubject()).isEqualTo(tokenClaims.getSubject());
    assertThat(tokenIntrospectionResponse.getAudience()).containsExactlyInAnyOrderElementsOf(tokenClaims.getAudience());
    assertThat(tokenIntrospectionResponse.getIssuer()).isEqualTo(tokenClaims.getIssuer());
    assertThat(tokenIntrospectionResponse.getId()).isEqualTo(tokenClaims.getId());
}

