@Test
public void loadAuthorizedClientWhenExistsButNotFoundInClientRegistrationRepositoryThenThrowDataRetrievalFailureException() {
    given(this.clientRegistrationRepository.findByRegistrationId(any())).willReturn(Mono.empty());
    Authentication principal = createPrincipal();
    OAuth2AuthorizedClient expected = createAuthorizedClient(principal, this.clientRegistration);
    this.authorizedClientService.saveAuthorizedClient(expected, principal).as(StepVerifier::create).verifyComplete();
    this.authorizedClientService.loadAuthorizedClient(this.clientRegistration.getRegistrationId(), principal.getName()).as(StepVerifier::create).verifyErrorSatisfies((exception) -> assertThat(exception).isInstanceOf(DataRetrievalFailureException.class).hasMessage("The ClientRegistration with id '" + this.clientRegistration.getRegistrationId() + "' exists in the data source, however, it was not found in the ReactiveClientRegistrationRepository."));
}

