@Test
public void authorizeWhenBlockingExecutionAndContextPropagationEnabledThenContextPropagated() throws InterruptedException {
    Hooks.enableAutomaticContextPropagation();
    given(this.clientRegistrationRepository.findByRegistrationId(eq(this.clientRegistration.getRegistrationId()))).willReturn(Mono.just(this.clientRegistration));
    given(this.authorizedClientProvider.authorize(any(OAuth2AuthorizationContext.class))).willReturn(Mono.just(this.authorizedClient));
    OAuth2AuthorizeRequest authorizeRequest = OAuth2AuthorizeRequest.withClientRegistrationId(this.clientRegistration.getRegistrationId()).principal(this.principal).build();
    CountDownLatch countDownLatch = new CountDownLatch(1);
    Runnable task = () -> {
        try {
            OAuth2AuthorizedClient authorizedClient = this.authorizedClientManager.authorize(authorizeRequest).block();
            assertThat(authorizedClient).isSameAs(this.authorizedClient);
        } finally {
            countDownLatch.countDown();
        }
    };
    try (SimpleAsyncTaskExecutor taskExecutor = new SimpleAsyncTaskExecutor()) {
        ContextSnapshotFactory contextSnapshotFactory = ContextSnapshotFactory.builder().build();
        ExecutorService executorService = ContextExecutorService.wrap(new ExecutorServiceAdapter(taskExecutor), contextSnapshotFactory);
        Mono.fromRunnable(() -> executorService.execute(task)).contextWrite(this.context).block();
    }
    countDownLatch.await();
    verify(this.authorizedClientProvider).authorize(any(OAuth2AuthorizationContext.class));
}

