    assertThat(key2.getAlgorithm().getName()).isEqualTo("RS256");
    assertThat(key2.getKeyType()).isEqualTo(KeyType.RSA);
    assertThat(key2.getKeyUse()).isEqualTo(KeyUse.SIGNATURE);
}

