}

private void assertSecurityContextLoaded(ThreadFactory threadFactory) {
    SecurityContextImpl context = new SecurityContextImpl(this.principal);
    given(this.repository.load(any())).willReturn(Mono.just(context));
    // @formatter:off
    WebFilter subscribeOnThreadFactory = (exchange, chain) -> chain.filter(exchange).subscribeOn(Schedulers.newSingle(threadFactory));
    WebFilter assertSecurityContext = (exchange, chain) -> ReactiveSecurityContextHolder.getContext().map(SecurityContext::getAuthentication).doOnSuccess((authentication) -> assertThat(authentication).isSameAs(this.principal)).then(chain.filter(exchange));
    // @formatter:on
    this.handler = WebTestHandler.bindToWebFilters(subscribeOnThreadFactory, this.filter, assertSecurityContext);
    this.handler.exchange(this.exchange);
}

