@Test
public void negotiationStrategyThrowsHMTNAE() throws HttpMediaTypeNotAcceptableException {
    given(this.negotiationStrategy.resolveMediaTypes(any(NativeWebRequest.class))).willThrow(new HttpMediaTypeNotAcceptableException("oops"));
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.ALL);
    assertThat(this.matcher.matches(this.request)).isFalse();
}

@Test
public void mediaAllMatches() throws Exception {
    given(this.negotiationStrategy.resolveMediaTypes(any(NativeWebRequest.class))).willReturn(Arrays.asList(MediaType.ALL));
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.TEXT_HTML);
    assertThat(this.matcher.matches(this.request)).isTrue();
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.APPLICATION_XHTML_XML);
    assertThat(this.matcher.matches(this.request)).isTrue();
}

@Test
public void multipleMediaType() throws HttpMediaTypeNotAcceptableException {
    given(this.negotiationStrategy.resolveMediaTypes(any(NativeWebRequest.class))).willReturn(Arrays.asList(MediaType.TEXT_PLAIN, MediaType.APPLICATION_XHTML_XML, MediaType.TEXT_HTML));
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.APPLICATION_ATOM_XML, MediaType.TEXT_HTML);
    assertThat(this.matcher.matches(this.request)).isTrue();
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.APPLICATION_XHTML_XML, MediaType.APPLICATION_JSON);
    assertThat(this.matcher.matches(this.request)).isTrue();
    this.matcher = new MediaTypeRequestMatcher(this.negotiationStrategy, MediaType.APPLICATION_FORM_URLENCODED, MediaType.APPLICATION_JSON);
    assertThat(this.matcher.matches(this.request)).isFalse();
}

